    }
}
```

What will be the output of the following program?

```java
public class Main {
    public static void main(String[] args) {
        int arr[] = {11, 9, 10, 45, 22};
        SomeFunction(arr);
        for (int i : arr) {
            System.out.println(i % 2);
        }
    }
    static void SomeFunction(int arr[]) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++)
            for (int j = 0; j < n - i - 1; j++)
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
    }
}
```

